BEGIN;

CREATE TYPE "MembershipRequestStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "MembershipCommitteeDecision" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');

CREATE TABLE "membership_request" (
    "membership_request_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "person_id" INTEGER NOT NULL,
    "status" "MembershipRequestStatus" NOT NULL DEFAULT 'PENDING',
    "application_data" JSONB NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "membership_request_pkey" PRIMARY KEY ("membership_request_id"),
    CONSTRAINT "membership_request_person_id_key" UNIQUE ("person_id"),
    CONSTRAINT "membership_request_person_id_fkey" FOREIGN KEY ("person_id") REFERENCES "person"("person_id") ON DELETE RESTRICT ON UPDATE NO ACTION
);

CREATE TABLE "membership_request_committee" (
    "membership_request_committee_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "membership_request_id" INTEGER NOT NULL,
    "committee_id" INTEGER NOT NULL,
    "requested_role" VARCHAR(100) NOT NULL,
    "status" "MembershipCommitteeDecision" NOT NULL DEFAULT 'PENDING',
    "decided_by_member_id" INTEGER,
    "decided_at" TIMESTAMPTZ(6),
    CONSTRAINT "membership_request_committee_pkey" PRIMARY KEY ("membership_request_committee_id"),
    CONSTRAINT "membership_request_committee_request_committee_key" UNIQUE ("membership_request_id", "committee_id"),
    CONSTRAINT "membership_request_committee_request_fkey" FOREIGN KEY ("membership_request_id") REFERENCES "membership_request"("membership_request_id") ON DELETE CASCADE ON UPDATE NO ACTION,
    CONSTRAINT "membership_request_committee_committee_fkey" FOREIGN KEY ("committee_id") REFERENCES "committee"("committee_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "membership_request_committee_reviewer_fkey" FOREIGN KEY ("decided_by_member_id") REFERENCES "member"("member_id") ON DELETE RESTRICT ON UPDATE NO ACTION,
    CONSTRAINT "membership_request_committee_requested_role_check" CHECK ("requested_role" IN ('Leader', 'Co-Leader', 'Advisor', 'Member')),
    CONSTRAINT "membership_request_committee_decision_check" CHECK (
      ("status" = 'PENDING' AND "decided_by_member_id" IS NULL AND "decided_at" IS NULL)
      OR ("status" IN ('APPROVED', 'REJECTED') AND "decided_by_member_id" IS NOT NULL AND "decided_at" IS NOT NULL)
    )
);

CREATE INDEX "membership_request_status_created_idx" ON "membership_request" ("status", "created_at");
CREATE INDEX "membership_request_committee_queue_idx" ON "membership_request_committee" ("committee_id", "status", "membership_request_id");

-- applications.decide is an existing committee-scoped permission reference.
-- Only DATA and PR leadership receive it for their own committee requests.
INSERT INTO "committee_permission" ("committee_id", "committee_role", "code", "applies_to", "include_sub_committees")
SELECT c."committee_id", roles."committee_role", 'applications.decide', 'own', false
FROM "committee" c
CROSS JOIN (VALUES ('Leader'), ('Co-Leader')) AS roles("committee_role")
WHERE c."committee_code" IN ('DATA', 'PR')
  AND NOT EXISTS (
    SELECT 1 FROM "committee_permission" existing
    WHERE existing."committee_id" = c."committee_id"
      AND existing."committee_role" = roles."committee_role"
      AND existing."code" = 'applications.decide'
      AND existing."applies_to" = 'own'
  );

COMMIT;
